SELECT ?id ?artist WHERE {
  ?card a <http://bird-bird_card_games-ontology-20260804-230127/ontology/vkg-bird_card_games/Card> ;
        <http://bird-bird_card_games-ontology-20260804-230127/ontology/vkg-bird_card_games/Card/id> ?id ;
        <http://bird-bird_card_games-ontology-20260804-230127/ontology/vkg-bird_card_games/Card/artist> ?artist ;
        <http://bird-bird_card_games-ontology-20260804-230127/ontology/vkg-bird_card_games/Card/uuid> ?uuid .
  OPTIONAL { ?card <http://bird-bird_card_games-ontology-20260804-230127/ontology/vkg-bird_card_games/Card/power> ?power }
  FILTER (!BOUND(?power))
  ?leg a <http://bird-bird_card_games-ontology-20260804-230127/ontology/vkg-bird_card_games/Legality> ;
       <http://bird-bird_card_games-ontology-20260804-230127/ontology/vkg-bird_card_games/Legality/uuid> ?uuid ;
       <http://bird-bird_card_games-ontology-20260804-230127/ontology/vkg-bird_card_games/Legality/format> "commander" ;
       <http://bird-bird_card_games-ontology-20260804-230127/ontology/vkg-bird_card_games/Legality/status> "Legal" .
}

