WHERE {
  {
    SELECT (COUNT(DISTINCT ?c) AS ?cnt_total)
    WHERE {
      ?c a <http://bird-bird_card_games-ontology-20260804-230127/ontology/vkg-bird_card_games/Card> .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?c2) AS ?cnt_cn)
    WHERE {
      ?c2 a <http://bird-bird_card_games-ontology-20260804-230127/ontology/vkg-bird_card_games/Card> ;
          <http://bird-bird_card_games-ontology-20260804-230127/ontology/vkg-bird_card_games/Card/uuid> ?uuid .
      ?fd a <http://bird-bird_card_games-ontology-20260804-230127/ontology/vkg-bird_card_games/ForeignData> ;
          <http://bird-bird_card_games-ontology-20260804-230127/ontology/vkg-bird_card_games/ForeignData/uuid> ?uuid ;
          <http://bird-bird_card_games-ontology-20260804-230127/ontology/vkg-bird_card_games/ForeignData/language> "Chinese Simplified" .
    }
  }
}

